import unittest

from rosterkit.models import Student
from rosterkit.reader import read_roster
from rosterkit.seating import seating_lines
from tests.support import data_file

class SeatingLinesTests(unittest.TestCase):
    def setUp(self):
        self.students = read_roster(data_file("roster.csv"))

    def test_two_seats_per_row_sorted_by_last_name(self):
        self.assertEqual(
            seating_lines(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quillon, Sefa | Thistle, Bram",
                "Row 3: Varrow, Ines",
            ],
        )

    def test_one_seat_per_row(self):
        lines = seating_lines(self.students, 1)
        self.assertEqual(len(lines), 5)
        self.assertEqual(lines[0], "Row 1: Dunmere, Piet")

    def test_seats_more_than_students_gives_one_row(self):
        lines = seating_lines(self.students, 20)
        self.assertEqual(
            lines,
            [
                "Row 1: Dunmere, Piet | Halloway, Juno | Quillon, Sefa | "
                "Thistle, Bram | Varrow, Ines"
            ],
        )

    def test_input_order_does_not_matter(self):
        reversed_students = list(reversed(self.students))
        self.assertEqual(
            seating_lines(reversed_students, 2), seating_lines(self.students, 2)
        )

    def test_last_name_sort_ignores_case(self):
        students = [
            Student("1", "bolt", "Ada", "A"),
            Student("2", "Adams", "Ben", "A"),
            Student("3", "Carver", "Cy", "A"),
        ]
        self.assertEqual(
            seating_lines(students, 3),
            ["Row 1: Adams, Ben | bolt, Ada | Carver, Cy"],
        )

    def test_same_last_name_sorts_by_first_name(self):
        students = [
            Student("1", "Lane", "Zoe", "A"),
            Student("2", "Lane", "Amos", "A"),
        ]
        self.assertEqual(
            seating_lines(students, 1),
            ["Row 1: Lane, Amos", "Row 2: Lane, Zoe"],
        )

    def test_zero_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_lines(self.students, 0)

    def test_negative_seats_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_lines(self.students, -3)

    def test_no_students_is_rejected(self):
        with self.assertRaises(ValueError):
            seating_lines([], 2)

    def test_generator_input_is_accepted(self):
        lines = seating_lines((student for student in self.students), 5)
        self.assertEqual(len(lines), 1)
